/* Jx9 script: compile only (lexer, keyword lookup, parser, code generator)
 * and dump the generated bytecode; nothing is executed. */
#include <stdint.h>
#include "fuzz_common.h"

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  unqlite *db;
  unqlite_vm *vm;
  if (size > 65536) return -1;
  if (unqlite_open(&db, ":mem:", UNQLITE_OPEN_IN_MEMORY) != UNQLITE_OK) return 0;
  if (unqlite_compile(db, (const char *)data, (int)size, &vm) == UNQLITE_OK) {
    unqlite_vm_dump(vm, fuzz_discard, NULL);
    unqlite_vm_release(vm);
  }
  unqlite_close(db);
  return 0;
}
